{
"initial": {"done":[],"queue":["clover","poppy"]},
"tasks": null,
"rule": {
"table": {
"clover": [],
"dove": [],
"elm": ["thistle"],
"lemon": [],
"maple": ["thistle"],
"poppy": ["maple", "quince", "lemon"],
"quince": ["thistle", "walnut"],
"thistle": [],
"tulip": ["quince", "thistle"],
"walnut": ["dove"]
},
"action": "remove the alphabetically first job from the queue and append it to the end of the done list; then add each of that job's follow-up jobs to the queue, skipping any job that is already in the done list or already in the queue, and keep the queue in alphabetical order"
},
"until": "the queue is empty"
}

